// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EmergencyOracleFactory} from "../src/EmergencyOracleFactory.sol";

contract InvMutTest is Test {
    EmergencyOracleFactory c;
    function setUp() public {
        c = new EmergencyOracleFactory();
    }

    function testFuzz_property(address caller, string calldata description) public {
        vm.assume(caller != address(0));
        vm.prank(caller);
        bool ok;
        try c.newEmergencyOracle(description) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok);
    }
}
